UPDATE kv_store SET value = json_set(value, '$.products[29].packagings', json('[{"type":"bottle","name":"Chai Bơm Định Lượng","image":"https://images.unsplash.com/photo-1540555700478-4be289fbecef?q=80&w=600","description":"Vòi bơm định lượng tiện lợi, kiểm soát lượng dùng, lý tưởng cho nước tẩy trang dùng hằng ngày."},{"type":"bottle","name":"Chai Nắp Bật Tiện Lợi","image":"https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?q=80&w=600","description":"Nắp bật (flip-top) thao tác nhanh một tay, kín khít, gọn gàng trên bàn trang điểm."},{"type":"bottle","name":"Chai PET Dung Tích Lớn","image":"https://images.unsplash.com/photo-1526947425960-945c6e72858f?q=80&w=600","description":"Chai PET bền nhẹ dung tích lớn, tối ưu chi phí cho dòng dùng thường xuyên."},{"type":"bottle","name":"Chai Thủy Tinh Nắp Vặn","image":"https://images.unsplash.com/photo-1597931752949-98c74b5b159f?q=80&w=600","description":"Chai nắp vặn kín, định lượng chuẩn, sang trọng cho nước tẩy trang/toner cao cấp."}]')) WHERE key='sheets_config';
